import React, { ReactNode, useRef } from 'react';

import { Store, createStore } from '../../../core/store/store.js';
import { PieChartStateContext } from '../context/PieChartStateContext.js';
import { initialState, PieChartState } from '../types/state.js';

export const StoreProvider = ({ children }: { children: ReactNode }) => {
  const storeRef = useRef<Store<PieChartState>>();

  storeRef.current = createStore(initialState);

  return (
    <PieChartStateContext.Provider value={storeRef.current}>
      {children}
    </PieChartStateContext.Provider>
  );
};
